/**
 * @file DOM helpers for the options inside a listbox.
 *
 * Two states sit on an option and they are not the same thing. `data-highlighted` is the highlighted option — where the keyboard or pointer is, one option at a time. `aria-selected` is the selection — what the person chose, which can be more than one.
 */
import { randomString } from '@splendidlabz/utils/dom'
import { removeAccents } from './match.js'

/**
 * prepareOptions
 * Gives options written as plain `li` their role, id, label and value, and gives every option its check.
 *
 * Options rendered by Svelte already carry their role, id, label and value in their markup, so only `li` without a role are touched for those.
 *
 * The check is copied in here rather than rendered by Svelte because slot options are markup the person wrote, and Svelte can't render a snippet inside it. Copying it into every option keeps slot options, item options and created options the same.
 *
 * @param {object} opts
 * @param {HTMLElement} opts.listbox
 * @param {boolean} [opts.multiple] Let more than one option be selected
 * @param {HTMLElement | null} [opts.check] Check the options copy
 * @returns {void}
 */
export function prepareOptions({ listbox, multiple = false, check }) {
  listbox.setAttribute('aria-multiselectable', String(multiple))

  /** @type {NodeListOf<HTMLLIElement>} */
  const plainOptions = listbox.querySelectorAll('li:not([role])')
  for (const option of plainOptions) {
    option.setAttribute('role', 'option')
    option.id ||= randomString(8)
    option.dataset.label = option.textContent.trim()
  }

  // An option submits its value, and the label is the value when the markup names no other.
  for (const option of getAllOptions(listbox)) {
    option.dataset.value ??= option.dataset.label
  }

  // The order the markup wrote, so filtering can put the list back after ranking it
  getAllOptions(listbox).forEach((option, index) => {
    option.dataset.position ??= String(index)
  })

  // Comes after the label is read, so the check's own markup never becomes part of it
  if (check) {
    for (const option of getAllOptions(listbox)) {
      if (!option.querySelector('.option-check'))
        option.append(check.cloneNode(true))
    }
  }

  // A multiselectable listbox states every option's selected state, not only the chosen ones.
  if (!multiple) return
  for (const option of getAllOptions(listbox)) {
    if (!option.hasAttribute('aria-selected')) {
      option.setAttribute('aria-selected', 'false')
    }
  }
}

/**
 * showOptionCount
 * Caps the listbox at the height of its first `size` options, so that many show before it scrolls.
 *
 * The heights are summed rather than multiplied, so an option that wraps onto a second line still counts as one option.
 *
 * @param {object} opts
 * @param {HTMLElement} opts.listbox
 * @param {number} [opts.size] How many options to show
 * @returns {void}
 */
export function showOptionCount({ listbox, size }) {
  if (!size) return

  const options = getVisibleOptions(listbox).slice(0, size)
  if (!options.length) return

  const height = options.reduce(
    (total, option) => total + option.getBoundingClientRect().height,
    0,
  )

  // Options measure 0 inside a closed popover, and a cap of 0 would hide every one
  if (!height) return
  listbox.style.setProperty('--options-max-height', `${height}px`)
}

/**
 * sortOptions
 * Puts the options into the DOM in the order they read, because a screen reader reads the DOM.
 *
 * Svelte renders a created value and the create option from their own blocks below the list, and each block inserts against an anchor node. An option moved past one of those anchors sends the block's next render above the list, so everything stays ahead of the first anchor.
 *
 * @param {object} opts
 * @param {HTMLElement} opts.listbox
 * @param {HTMLElement[]} opts.options Options in the order they read
 * @returns {void}
 */
export function sortOptions({ listbox, options }) {
  if (!options.length) return

  const group = new Set(options)
  const anchor = /** @type {HTMLElement} */ (
    getAllOptions(listbox).findLast(option => group.has(option))
  ).nextSibling

  for (const option of options) listbox.insertBefore(option, anchor)
}

/**
 * getAllOptions
 * Gets every option, including the hidden ones.
 *
 * @param {HTMLElement} listbox
 * @returns {HTMLElement[]}
 */
export function getAllOptions(listbox) {
  return Array.from(listbox.querySelectorAll('[role="option"]'))
}

/**
 * getVisibleOptions
 * Gets the options that aren't filtered out, in the order they appear on screen.
 *
 * @param {HTMLElement} listbox
 * @returns {HTMLElement[]}
 */
export function getVisibleOptions(listbox) {
  return getAllOptions(listbox).filter(option => !option.hidden)
}

/**
 * getHighlightedOption
 * Gets the highlighted option.
 *
 * @param {HTMLElement} listbox
 * @returns {HTMLElement | null}
 */
export function getHighlightedOption(listbox) {
  return listbox.querySelector('[role="option"][data-highlighted]')
}

/**
 * highlightOption
 * Highlights one option.
 *
 * @param {object} opts
 * @param {HTMLElement} opts.listbox
 * @param {HTMLElement} opts.option
 * @param {boolean} [opts.shouldScroll] Scroll option into view
 * @param {ScrollBehavior} [opts.behaviour] How the scroll runs
 * @returns {void}
 */
export function highlightOption(opts) {
  const { listbox, option, shouldScroll = true, behaviour } = opts

  clearHighlight(listbox)
  option.dataset.highlighted = ''
  if (shouldScroll) {
    option.scrollIntoView({ block: 'nearest', behavior: behaviour })
  }
}

/**
 * clearHighlight
 * Removes the highlight from every option.
 *
 * @param {HTMLElement} listbox
 * @returns {void}
 */
export function clearHighlight(listbox) {
  getHighlightedOption(listbox)?.removeAttribute('data-highlighted')
}

/**
 * getSelectedOptions
 * Gets the options the person chose.
 *
 * @param {HTMLElement} listbox
 * @returns {HTMLElement[]}
 */
export function getSelectedOptions(listbox) {
  return Array.from(
    listbox.querySelectorAll('[role="option"][aria-selected="true"]'),
  )
}

/**
 * selectOption
 * Single-select replaces the selection. Multi-select toggles this option.
 *
 * @param {object} opts
 * @param {HTMLElement} opts.listbox
 * @param {HTMLElement} opts.option
 * @returns {void}
 */
export function selectOption({ listbox, option }) {
  const multiselectable =
    listbox.getAttribute('aria-multiselectable') === 'true'

  if (!multiselectable) {
    for (const selected of getSelectedOptions(listbox)) {
      selected.removeAttribute('aria-selected')
    }
    option.setAttribute('aria-selected', 'true')
    return
  }

  option.setAttribute(
    'aria-selected',
    String(option.getAttribute('aria-selected') !== 'true'),
  )
}

/**
 * getAdjacentOption
 * Gets the visible option before or after the highlighted one.
 *
 * With nothing highlighted, `next` gives the first option and `prev` the last.
 *
 * @param {object} opts
 * @param {HTMLElement} opts.listbox
 * @param {'next' | 'prev'} opts.direction
 * @param {boolean} opts.loop Wrap past either end
 * @returns {HTMLElement | null}
 */
export function getAdjacentOption({ listbox, direction, loop }) {
  const options = getVisibleOptions(listbox)
  if (!options.length) return null

  const highlightedOption = getHighlightedOption(listbox)
  const currentIndex = highlightedOption
    ? options.indexOf(highlightedOption)
    : -1
  const lastIndex = options.length - 1

  if (currentIndex === -1)
    return direction === 'next' ? options[0] : options[lastIndex]

  let index = direction === 'next' ? currentIndex + 1 : currentIndex - 1
  if (index > lastIndex) index = loop ? 0 : lastIndex
  if (index < 0) index = loop ? lastIndex : 0
  return options[index]
}

/**
 * getOptionStartingWith
 * Gets the first visible option whose label starts with typed text, searching from an option and wrapping past the end.
 *
 * Case and accents are ignored, so "e" reaches "Éire".
 *
 * @param {object} opts
 * @param {HTMLElement} opts.listbox
 * @param {string} opts.text Typed text
 * @param {HTMLElement | null} [opts.from] Option the search starts at
 * @returns {HTMLElement | null}
 */
export function getOptionStartingWith({ listbox, text, from }) {
  const options = getVisibleOptions(listbox)
  const start = from ? options.indexOf(from) : 0
  const typed = removeAccents(text).toLowerCase()

  return (
    [...options.slice(start), ...options.slice(0, start)].find(option =>
      removeAccents(/** @type {string} */ (option.dataset.label))
        .toLowerCase()
        .startsWith(typed),
    ) ?? null
  )
}
